# %% ../../nbs/handlers/maris_legacy.ipynb #178e3892
class CastStationToStringCB(PerGroupCB):
    "Convert STATION column to string type, filling any missing values with empty string"
    def each_grp(self, grp, df, tfm):
        if 'STATION' in df.columns: df['STATION'] = df['STATION'].fillna('').astype('string')

# %% ../../nbs/handlers/maris_legacy.ipynb #819703e6
class DropNAColumnsCB(PerGroupCB):
    "Drop columns containing only NaN or 'Not available' (id=0 in MARIS lookup tables), except those in `keep`"
    def __init__(self,
        na_value:int=0, # MARIS NA id to drop
        keep:tuple=('SMP_ID_PROVIDER',) # Columns to keep even when empty
    ): store_attr()
    def isMarisNA(self, col:pd.Series)->bool: return len(col.unique()) == 1 and col.iloc[0] == self.na_value
    def dropMarisNA(self, df:pd.DataFrame)->pd.DataFrame:
        return df.drop(columns=[c for c in df.columns if c not in self.keep and self.isMarisNA(df[c])])
    def each_grp(self, grp:str, df:pd.DataFrame, tfm:Transformer):
        empty = [c for c in df.columns if c not in self.keep and df[c].isna().all()]
        tfm.dfs[grp] = self.dropMarisNA(df.drop(columns=empty))

# %% ../../nbs/handlers/maris_legacy.ipynb #0c0f2450
lut_dl = get_lut('DL', key='name', value='id')

# %% ../../nbs/handlers/maris_legacy.ipynb #e5352604
class CastSampleIDCB(PerGroupCB):
    "Cast SMP_ID to int and SMP_ID_PROVIDER to string (renamed from samplabcode in the pipeline)"
    def each_grp(self, grp, df, tfm):
        df['SMP_ID'] = df['SMP_ID'].astype(int)
        df['SMP_ID_PROVIDER'] = df['SMP_ID_PROVIDER'].fillna('').astype(str)

# %% ../../nbs/handlers/maris_legacy.ipynb #b05c8982
def get_cbs() -> list:
    "Callbacks, in pipeline order, that turn MARIS dump data into MARIS-standard DataFrames"
    return [  # chkstyle: ignore-node
        RenameColumnsCB(cois_renaming_rules),
        CastStationToStringCB(),
        DropNAColumnsCB(),
        RemapCB(lut=lut_dl, col_src='DL', col_remap='DL', default_val=0),
        ParseTimeCB(),
        EncodeTimeCB(),
        SanitizeLonLatCB(),
        CastSampleIDCB()]

