# %% ../../nbs/handlers/maris_legacy.ipynb #09e988c3
def get_zotero_key(
    dfs:dict # Dict of {group_name: DataFrame} per sample type
)->str: # Zotero key extracted from URL
    "Extract Zotero bibliography key from the MARIS dump DataFrame"
    return dfs[next(iter(dfs))][['zoterourl']].iloc[0].values[0].split('/')[-1]

# %% ../../nbs/handlers/maris_legacy.ipynb #7fd56197
def get_fname(
    dfs:dict # Dict of {group_name: DataFrame} per sample type
)->str: # NetCDF filename like "12345.nc"
    "Construct NetCDF filename from the ref_id in the data"
    return f"{next(iter(dfs.values()))['ref_id'].iloc[0]}.nc"

# %% ../../nbs/handlers/maris_legacy.ipynb #ca5357b7
def get_attrs(
    tfm:Transformer, # Transformer after running the pipeline
    zotero_key:str, # Zotero key of the reference
    kw:list=kw, # Keywords
)->dict: # Global attributes
    "Retrieve global attributes from MARIS dump"
    return GlobAttrsFeeder(tfm.dfs, cbs=[  # chkstyle: ignore-node
        BboxCB(), DepthRangeCB(), TimeRangeCB(), ZoteroCB(zotero_key),
        KeyValuePairCB('keywords', ', '.join(kw)),
        KeyValuePairCB('publisher_postprocess_logs', ', '.join(tfm.logs))])()

# %% ../../nbs/handlers/maris_legacy.ipynb #63419143
def encode(
    dest: str, # Path to the folder where the NetCDF output will be saved
    src: str = None, # Path to the MARIS dump data in CSV format
    **kwargs # Additional keyword arguments
):
    "MARIS legacy database dump"
    assert src, "maris_legacy requires `src`, the path to the MARIS dump CSV"
    dataloader = DataLoader(src)
    ref_ids = parse_ref_ids(kwargs.get('ref_ids'), valid=dataloader.df.ref_id.unique())
    print('Encoding ...')
    for i, ref_id in enumerate(ref_ids):
        dfs = dataloader(ref_id=ref_id)
        print(f'{i+1}/{len(ref_ids)}: ref_id={ref_id} -> {dest}/{get_fname(dfs)}')
        tfm = Transformer(dfs, cbs=get_cbs())
        tfm()
        encoder = NetCDFEncoder(tfm.dfs, dest_fname=Path(dest)/get_fname(dfs),
            global_attrs=get_attrs(tfm, zotero_key=get_zotero_key(dfs)), verbose=kwargs.get('verbose', False))
        encoder.encode()
